uint8_t audio_app_meas_table_n_levels( uint8_t tone_row )
{
    if( tone_row >= 167u )  { tone_row = 0u; }
    return k_rows[tone_row].n_levels;
}

const meas_tone_table_t *audio_app_meas_table( uint8_t tone_row, uint8_t level_idx )
{
    if( tone_row >= 167u )  { tone_row = 0u; }
    /* A row that carries fewer levels CLAMPS TO ITS OWN 0 (-1 dBFS), which is the level
     * every fold-image measurement wants anyway.  Silently serving level 0 while the
     * console still says -60 dBFS would be the wrong kind of quiet, so the arm and
     * selection prints read level_dbfs back OUT of the table -- they always did.  Callers
     * that need to know before arming ask audio_app_meas_table_n_levels(). */
    if( level_idx >= k_rows[tone_row].n_levels ) { level_idx = 0u; }
    return &k_rows[tone_row].levels[level_idx];
}

